const CORREO_DEMO = 'leirbag23m11z@gmail.com';

const escapar = (valor = '') =>
  String(valor)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');

const codigoJornada = (jornada = {}) =>
  jornada.codigo ??
  jornada.codigo_jornada ??
  (jornada.id ? `JR-${String(jornada.id).padStart(5, '0')}` : 'Jornada');

const codigoPedido = (despacho = {}) => {
  const pedido = despacho.pedido ?? {};
  return (
    pedido.codigo ??
    pedido.numero ??
    despacho.codigo_pedido ??
    (despacho.pedido_id
      ? `PED-${String(despacho.pedido_id).padStart(5, '0')}`
      : 'Pedido')
  );
};

const obtenerCliente = (despacho = {}) => {
  const pedido = despacho.pedido ?? {};
  const cliente =
    despacho.cliente ??
    pedido.cliente ??
    {};

  return {
    id: cliente.id ?? despacho.cliente_id ?? null,
    nombre:
      cliente.nombre_completo ??
      cliente.nombre ??
      despacho.nombre_cliente ??
      'Cliente',
    correo:
      cliente.correo ??
      cliente.email ??
      despacho.correo_cliente ??
      pedido.correo_cliente ??
      'Correo no disponible',
  };
};

const plantilla = ({
  titulo,
  subtitulo,
  contenido,
  destinatarioPrevisto,
  tipo = 'Sistema',
}) => `
<div style="margin:0;padding:32px 16px;background:#f3f6fb;font-family:Arial,Helvetica,sans-serif;color:#17233b;">
  <div style="max-width:680px;margin:0 auto;background:#ffffff;border:1px solid #dbe4f0;border-radius:16px;overflow:hidden;box-shadow:0 10px 30px rgba(19,45,86,.10);">

    <div style="padding:24px 28px;background:#173f78;color:#ffffff;">
      <div style="font-size:12px;font-weight:700;letter-spacing:1.3px;text-transform:uppercase;opacity:.8;">
        TechSupply SCM · ${escapar(tipo)}
      </div>

      <h1 style="margin:8px 0 4px;font-size:23px;line-height:1.3;">
        ${escapar(titulo)}
      </h1>

      <p style="margin:0;font-size:14px;line-height:1.6;opacity:.88;">
        ${escapar(subtitulo)}
      </p>
    </div>

    <div style="padding:28px;">
      ${
        destinatarioPrevisto
          ? `
            <div style="margin-bottom:20px;padding:14px 16px;background:#fff8e8;border:1px solid #f3d58c;border-radius:10px;">
              <div style="font-size:11px;font-weight:700;color:#8a6516;text-transform:uppercase;">
                Simulación de destinatario
              </div>

              <div style="margin-top:5px;font-size:14px;color:#5e4a1d;">
                Este mensaje habría sido enviado a:
                <strong>${escapar(destinatarioPrevisto)}</strong>
              </div>
            </div>
          `
          : ''
      }

      ${contenido}

      <p style="margin:24px 0 0;font-size:12px;line-height:1.6;color:#7a8799;text-align:center;">
        Notificación automática de TechSupply SCM · Módulo Outbound
      </p>
    </div>
  </div>
</div>
`;

const tarjetaDato = (etiqueta, valor) => `
<td style="padding:14px;background:#f7f9fc;border:1px solid #e0e7f1;border-radius:10px;vertical-align:top;">
  <div style="font-size:11px;color:#677892;text-transform:uppercase;font-weight:700;">
    ${escapar(etiqueta)}
  </div>

  <div style="margin-top:6px;font-size:16px;font-weight:700;">
    ${escapar(valor)}
  </div>
</td>
`;

const crearItem = ({
  subject,
  html,
  destinatarioPrevisto = null,
  categoria,
}) => ({
  json: {
    to: CORREO_DEMO,
    subject,
    html,
    destinatario_previsto: destinatarioPrevisto,
    categoria,
  },
});

const salida = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const evento = String(body.evento ?? '').trim().toUpperCase();
  const datos = body.datos ?? {};

  const jornada = datos.jornada ?? {};
  const despachos =
    datos.despachos ??
    jornada.despachos ??
    [];

  if (evento === 'JORNADA_CREADA') {
    const jornadas =
      datos.jornadas ??
      (datos.jornada ? [datos.jornada] : []);

    const resumen = datos.resumen ?? {};

    const totalPedidos =
      resumen.pedidos_asignados ??
      despachos.length ??
      0;

    const filas = jornadas.length
      ? jornadas.map((j) => `
          <tr>
            <td style="padding:10px;border-bottom:1px solid #e3e9f1;">
              <strong>${escapar(codigoJornada(j))}</strong>
            </td>
            <td style="padding:10px;border-bottom:1px solid #e3e9f1;">
              ${escapar(j.total_pedidos ?? j.pedidos ?? 0)}
            </td>
            <td style="padding:10px;border-bottom:1px solid #e3e9f1;">
              ${escapar(j.total_puntos ?? j.puntos ?? 0)}
            </td>
          </tr>
        `).join('')
      : `
          <tr>
            <td colspan="3" style="padding:14px;text-align:center;color:#677892;">
              Planificación recibida correctamente.
            </td>
          </tr>
        `;

    const contenido = `
      <table role="presentation" style="width:100%;border-collapse:separate;border-spacing:10px;margin:0 -10px 18px;">
        <tr>
          ${tarjetaDato('Jornadas', resumen.total_jornadas ?? jornadas.length)}
          ${tarjetaDato('Pedidos asignados', totalPedidos)}
          ${tarjetaDato('Sin asignar', resumen.sin_asignar ?? 0)}
        </tr>
      </table>

      <table style="width:100%;border-collapse:collapse;border:1px solid #dfe7f1;border-radius:10px;overflow:hidden;">
        <thead>
          <tr style="background:#edf3fa;text-align:left;">
            <th style="padding:10px;">Jornada</th>
            <th style="padding:10px;">Pedidos</th>
            <th style="padding:10px;">Puntos</th>
          </tr>
        </thead>
        <tbody>${filas}</tbody>
      </table>
    `;

    salida.push(
      crearItem({
        categoria: 'ADMIN',
        subject: 'TechSupply SCM | Planificación logística generada',
        html: plantilla({
          tipo: 'Administración',
          titulo: 'Planificación logística generada',
          subtitulo:
            'El sistema completó la asignación automática de pedidos y recursos.',
          contenido,
        }),
      }),
    );
  }

  if (evento === 'JORNADA_INICIADA') {
    const codigo = codigoJornada(jornada);

    const contenidoAdmin = `
      <table role="presentation" style="width:100%;border-collapse:separate;border-spacing:10px;margin:0 -10px;">
        <tr>
          ${tarjetaDato('Jornada', codigo)}
          ${tarjetaDato(
            'Camión',
            jornada.camion?.codigo ??
            jornada.camion_codigo ??
            jornada.camion ??
            'No disponible'
          )}
        </tr>
        <tr>
          ${tarjetaDato(
            'Chofer',
            jornada.chofer?.nombre ??
            jornada.nombre_chofer ??
            'No disponible'
          )}
          ${tarjetaDato('Despachos', despachos.length)}
        </tr>
      </table>
    `;

    salida.push(
      crearItem({
        categoria: 'ADMIN',
        subject: `TechSupply SCM | ${codigo} inició su recorrido`,
        html: plantilla({
          tipo: 'Administración',
          titulo: 'Jornada iniciada',
          subtitulo:
            'La operación de reparto salió de bodega y se encuentra en curso.',
          contenido: contenidoAdmin,
        }),
      }),
    );

    const clientes = new Map();

    for (const despacho of despachos) {
      const cliente = obtenerCliente(despacho);
      const clave =
        cliente.id ??
        cliente.correo ??
        cliente.nombre;

      if (!clientes.has(clave)) {
        clientes.set(clave, {
          ...cliente,
          pedidos: [],
        });
      }

      clientes.get(clave).pedidos.push(codigoPedido(despacho));
    }

    for (const cliente of clientes.values()) {
      const listaPedidos = cliente.pedidos
        .map((pedido) => `
          <li style="margin:5px 0;">
            ${escapar(pedido)}
          </li>
        `)
        .join('');

      const contenidoCliente = `
        <p style="font-size:15px;line-height:1.7;color:#40536d;">
          Hola <strong>${escapar(cliente.nombre)}</strong>.
          La jornada <strong>${escapar(codigo)}</strong> inició su recorrido.
        </p>

        <div style="padding:16px;background:#edf5ff;border:1px solid #cfe1f7;border-radius:10px;">
          <strong>Pedidos incluidos:</strong>
          <ul style="margin:10px 0 0;padding-left:20px;">
            ${listaPedidos}
          </ul>
        </div>
      `;

      salida.push(
        crearItem({
          categoria: 'CLIENTE',
          destinatarioPrevisto: cliente.correo,
          subject:
            `[SIMULACIÓN: ${cliente.correo}] ` +
            'TechSupply SCM | Su pedido salió a reparto',
          html: plantilla({
            tipo: 'Notificación al cliente',
            titulo: 'Su pedido salió a reparto',
            subtitulo:
              'El camión asignado inició la jornada de distribución.',
            contenido: contenidoCliente,
            destinatarioPrevisto: cliente.correo,
          }),
        }),
      );
    }
  }

  if (
    evento === 'DESPACHO_ENTREGADO' ||
    evento === 'DESPACHO_NO_ENTREGADO'
  ) {
    const despacho = datos.despacho ?? datos;
    const cliente = obtenerCliente(despacho);
    const pedido = codigoPedido(despacho);
    const entregado = evento === 'DESPACHO_ENTREGADO';

    const contenido = `
      <p style="font-size:15px;line-height:1.7;color:#40536d;">
        Hola <strong>${escapar(cliente.nombre)}</strong>.
      </p>

      <div style="padding:18px;background:${entregado ? '#f1fbf6' : '#fff4f4'};border:1px solid ${entregado ? '#b9e5cc' : '#efc3c3'};border-radius:10px;">
        <div style="font-size:12px;font-weight:700;text-transform:uppercase;color:${entregado ? '#137546' : '#a33b3b'};">
          ${entregado ? 'Entrega completada' : 'Entrega no completada'}
        </div>

        <div style="margin-top:7px;font-size:20px;font-weight:800;">
          ${escapar(pedido)}
        </div>
      </div>
    `;

    salida.push(
      crearItem({
        categoria: 'CLIENTE',
        destinatarioPrevisto: cliente.correo,
        subject:
          `[SIMULACIÓN: ${cliente.correo}] TechSupply SCM | ` +
          `${entregado ? 'Pedido entregado' : 'Entrega no completada'}`,
        html: plantilla({
          tipo: 'Notificación al cliente',
          titulo:
            entregado
              ? 'Pedido entregado'
              : 'Entrega no completada',
          subtitulo:
            entregado
              ? 'La entrega fue registrada correctamente.'
              : 'El pedido continuará dentro del flujo operativo correspondiente.',
          contenido,
          destinatarioPrevisto: cliente.correo,
        }),
      }),
    );
  }

  if (evento === 'JORNADA_FINALIZADA') {
    const codigo = codigoJornada(jornada);

    const entregados = despachos.filter(
      (d) => d.estado === 'ENTREGADO',
    ).length;

    const noEntregados = despachos.filter(
      (d) => d.estado === 'NO_ENTREGADO',
    ).length;

    const contenido = `
      <table role="presentation" style="width:100%;border-collapse:separate;border-spacing:10px;margin:0 -10px;">
        <tr>
          ${tarjetaDato('Jornada', codigo)}
          ${tarjetaDato('Despachos', despachos.length)}
        </tr>
        <tr>
          ${tarjetaDato('Entregados', entregados)}
          ${tarjetaDato('No entregados', noEntregados)}
        </tr>
      </table>
    `;

    salida.push(
      crearItem({
        categoria: 'ADMIN',
        subject: `TechSupply SCM | ${codigo} finalizada`,
        html: plantilla({
          tipo: 'Administración',
          titulo: 'Jornada finalizada',
          subtitulo:
            'La operación de reparto fue cerrada correctamente.',
          contenido,
        }),
      }),
    );
  }
}

return salida;
